cd /Users/smaschek/dev/paigasus/paigasus-core
gh api graphql -F owner=SMK1085 -F repo=paigasus-core -F pr=48 -f query='query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      title
      reviewThreads(first:100) {
        nodes {
          id
          isResolved
          isOutdated
          comments(first:10) {
            nodes { databaseId body path line startLine originalLine author { login } }
          }
        }
      }
    }
  }
}' > /tmp/cr_threads.json 2>&1
echo "=== thread summary (all) ==="
jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | "\(.comments.nodes[0].author.login) | resolved=\(.isResolved) outdated=\(.isOutdated) | \(.comments.nodes[0].path):\(.comments.nodes[0].line) | id=\(.id)"' /tmp/cr_threads.json 2>/dev/null || { echo "jq failed; raw:"; head -50 /tmp/cr_threads.json; }
echo ""
echo "=== count of unresolved coderabbit threads ==="
jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false and (.comments.nodes[0].author.login|test("coderabbit";"i")))] | length' /tmp/cr_threads.json 2>/dev/null

